  "location": "test_room",
  "weather": "持续下雨",
  "lighting": "门厅灯光"
}
人物位置: {
  "test_room": {
    "id": "test_room",
    "type": "location",
    "name": "雨夜承诺：失约、补偿与刷好感现场"
  },
  "player": {
    "id": "player",
    "type": "character",
    "name": "玩家",
    "location": "test_room"
  },
  "shen": {
    "id": "shen",
    "type": "character",
    "name": "沈苒",
    "location": "test_room"
  },
  "raincoat": {
    "id": "raincoat",
    "type": "item",
    "name": "玩家唯一的雨衣",
    "location": "test_room"
  }
}
发生事件: [
  {
    "id": "t3_b0_e1",
    "type": "action",
    "actor": "player",
    "op": "give",
    "item": "raincoat",
    "target": "shen",
    "duration": 1.5,
    "details": {},
    "outcome": {
      "status": "success",
      "summary": "玩家唯一的雨衣已从玩家移至雨夜承诺：失约、补偿与刷好感现场。",
      "reason": "结果仅依据通过校验的动作效果。"
    }
  },
  {
    "id": "t3_b0_e2",
    "type": "speech",
    "actor": "player",
    "content": "这件确实是我的，借你用。",
    "target": "shen",
    "duration": 2,
    "parallelWith": [
      "e1"
    ],
    "audibility": "normal",
    "audience": []
  }
]

